const chartModels = [
 ['Astra (ICL)','GPT-6-Astra · ICL','#3456ef'],['OpenWAM-Alpha','OpenWAM-α','#26394c'],
 ['Qwen-RobotManip','Qwen-RobotManip','#8098f2'],['Pi05','π₀.₅','#7374b8'],
 ['InternVLA-A1.5','InternVLA-A1.5','#9b8ed0'],['Pi0','π₀','#9aa8bd'],
 ['GigaBrain-0.7','GigaBrain-0.7','#bac4d8'],['FastWAM','Fast-WAM','#7e9fbd']
];
const chartSpecs = {
 overall:{title:'Overall benchmark performance',groups:[['All tasks',null]],note:'Equal-weight means over 26 tasks; 510 episodes per system.'},
 mobility:{title:'Performance by mobility',field:'mobility',groups:[['Mobile','Mobile'],['Tabletop','Fixed']]},
 precision:{title:'Performance by precision requirement',field:'precision',groups:[['Low','Low'],['Medium','Medium'],['High','High']]},
 horizon:{title:'Performance by task horizon',field:'horizon',groups:[['Short','Short Horizon'],['Long','Long Horizon']]},
 perturbation:{title:'Performance under controlled perturbations',groups:[['Object'],['Background'],['Instruction'],['Mixed']],note:'Object: 24 tasks / 120 episodes. Other conditions: 26 tasks / 130 episodes. Five instances per task; values follow the report.',values:[[44.17,50.77,44.62,46.15],[52.50,61.54,60,44.62],[40.83,55.38,51.54,33.85],[41.67,42.31,46.15,34.62]]}
};
function reportChart(kind){return `<figure class="report-chart" data-chart="${kind}"></figure>`;}
function initCharts(){document.querySelectorAll('[data-chart]:not([data-chart-ready])').forEach(host=>{
 host.dataset.chartReady='true';const kind=host.dataset.chart,spec=chartSpecs[kind];
 if(['mobility','precision','horizon'].includes(kind)){initProfileChart(host,kind,spec);return;}
 const available=kind==='perturbation'?chartModels.slice(0,4):chartModels;
 let metric='sr',selected=available.map((_,i)=>kind==='overall'||i<3),ci=false;
 host.innerHTML=`<div class="chart-heading"><h4>${spec.title}</h4>${kind==='perturbation'?'<span>Success rate (%)</span>':'<div class="chart-metrics" aria-label="Chart metric"><button data-metric="sr" aria-pressed="true">SR (%)</button><button data-metric="score" aria-pressed="false">Score</button></div>'}${kind==='overall'?'<button class="chart-ci" data-ci aria-pressed="false" title="Wilson 95% interval on 510 episodes per system; ignores task clustering">95% interval</button>':''}</div><div class="chart-series" aria-label="Models to compare">${available.map(([key,label,color],i)=>`<button data-series="${i}" aria-pressed="${selected[i]}" style="--series:${color}"><i></i>${label}</button>`).join('')}</div><div class="chart-drawing"></div><p class="chart-readout" aria-live="polite">Hover over a bar or focus it to inspect its value.</p><figcaption>${spec.note||'Equal-weight task means within each group. Attribute groups overlap and do not isolate causal effects.'}</figcaption><details class="chart-data"><summary>View numerical data</summary><div class="table-scroll"></div></details>`;
 function draw(){
  const visible=available.map((m,i)=>({...{key:m[0],label:m[1],color:m[2]},index:i})).filter(m=>selected[m.index]);
  const groups=spec.groups.map(([label,value],gi)=>{const subset=tasks.filter(t=>!spec.field||t[spec.field]===value);return {label:label+(spec.field?` · ${subset.length} tasks`:''),values:visible.map(m=>({...m,value:spec.values?spec.values[m.index][gi]:chartAggregate(m.key,metric,spec.field,value,subset)*(metric==='sr'?100:1)}))};});
  const width=Math.max(280,Math.min(760,host.clientWidth)),left=width<500?132:158,right=62,plot=width-left-right,row=27,groupGap=34,height=52+groups.length*(visible.length*row+groupGap);
  const fmt=v=>metric==='sr'?v.toFixed(2)+'%':v.toFixed(4), max=metric==='sr'?100:1;
  let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" role="group" aria-label="${spec.title}: ${metric==='sr'?'success rate':'Score'}" font-family="Arial, Helvetica, sans-serif" font-size="12">`;
  for(let i=0;i<=4;i++){const x=left+plot*i/4;svg+=`<line x1="${x}" x2="${x}" y1="24" y2="${height-25}" stroke="#e4e8ed"/><text x="${x}" y="15" text-anchor="middle" fill="#77818b">${metric==='sr'?i*25:(i/4).toFixed(2)}</text>`;}
  let y=43;groups.forEach(g=>{if(kind!=='overall'){svg+=`<text x="0" y="${y}" fill="#283645" font-weight="600">${g.label}</text>`;y+=21;}g.values.forEach(m=>{const showCI=ci&&metric==='sr'&&kind==='overall',[lo,hi]=showCI?viz.wilson(m.value/100,510):[0,0];const label=`${g.label} — ${m.label}: ${fmt(m.value)}${showCI?` (95% interval ${(lo*100).toFixed(1)}–${(hi*100).toFixed(1)}%)`:''}`;const labelX=showCI?left+plot*hi+8:left+plot*m.value/max+7;svg+=`<g class="chart-mark" tabindex="0" aria-label="${label}"><title>${label}</title><rect x="0" y="${y-15}" width="${width}" height="26" fill="transparent"/>${chartModelLabel(m.label,left,y)}<rect x="${left}" y="${y-12}" width="${plot}" height="16" rx="7" class="viz-track"/><rect x="${left}" y="${y-12}" width="${plot*m.value/max}" height="16" rx="7" fill="${m.color}" class="viz-bar-fill"/>${showCI?`<line x1="${left+plot*lo}" x2="${left+plot*hi}" y1="${y-4}" y2="${y-4}" class="viz-ci"/><line x1="${left+plot*lo}" x2="${left+plot*lo}" y1="${y-9}" y2="${y+1}" class="viz-ci"/><line x1="${left+plot*hi}" x2="${left+plot*hi}" y1="${y-9}" y2="${y+1}" class="viz-ci"/>`:''}<text x="${labelX}" y="${y}" fill="#273542">${fmt(m.value)}</text></g>`;y+=row;});y+=kind==='overall'?0:13;});
  host.querySelector('.chart-drawing').innerHTML=svg+'</svg>';
  host.querySelector('.chart-data .table-scroll').innerHTML=`<table><caption>${spec.title} · ${metric==='sr'?'SR (%)':'Score'}</caption><thead><tr><th>Group</th>${visible.map(m=>`<th>${m.label}</th>`).join('')}</tr></thead><tbody>${groups.map(g=>`<tr><th scope="row">${g.label}</th>${g.values.map(m=>`<td>${fmt(m.value)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
  host.querySelectorAll('.chart-mark').forEach(mark=>{const show=()=>host.querySelector('.chart-readout').textContent=mark.getAttribute('aria-label');mark.addEventListener('pointerenter',show);mark.addEventListener('focus',show);mark.addEventListener('click',show);});
 }
 host.addEventListener('click',e=>{const metricButton=e.target.closest('[data-metric]'),seriesButton=e.target.closest('[data-series]'),ciButton=e.target.closest('[data-ci]');if(metricButton){metric=metricButton.dataset.metric;host.querySelectorAll('[data-metric]').forEach(b=>b.setAttribute('aria-pressed',String(b===metricButton)));}else if(ciButton){ci=!ci;ciButton.setAttribute('aria-pressed',String(ci));}else if(seriesButton){const i=+seriesButton.dataset.series;if(selected[i]&&selected.filter(Boolean).length===1)return;selected[i]=!selected[i];seriesButton.setAttribute('aria-pressed',String(selected[i]));}else return;draw();host.querySelector('.chart-readout').textContent='Hover over a bar or focus it to inspect its value.';});draw();let lastWidth=host.clientWidth;const resize=new ResizeObserver(()=>{if(!host.isConnected){resize.disconnect();return;}if(host.clientWidth!==lastWidth){lastWidth=host.clientWidth;draw();}});resize.observe(host);
 });}
// Capability profile: every system on one line per task group, emphasized systems drawn larger.
function initProfileChart(host,kind,spec){
 const available=chartModels;let metric='sr';const highlighted=new Set(['Astra (ICL)','OpenWAM-Alpha']);
 host.innerHTML=`<div class="chart-heading"><h4>${spec.title}</h4><div class="chart-metrics" aria-label="Chart metric"><button data-metric="sr" aria-pressed="true">SR (%)</button><button data-metric="score" aria-pressed="false">Score</button></div></div><div class="chart-series" aria-label="Systems to emphasize">${available.map(([key,label,color])=>`<button data-series="${key}" aria-pressed="${highlighted.has(key)}" style="--series:${color}"><i></i>${label}</button>`).join('')}</div><div class="chart-drawing" data-viz-linked></div><p class="profile-note"><span><i></i>Dashed ring marks the best system in each group</span><span>All eight systems are shown; emphasized systems are drawn larger.</span></p><p class="chart-readout" aria-live="polite">Hover over a dot to inspect a system, or press a chip to emphasize it.</p><figcaption>${spec.note||'Equal-weight task means within each group. Attribute groups overlap and do not isolate causal effects.'}</figcaption><details class="chart-data"><summary>View numerical data</summary><div class="table-scroll"></div></details>`;
 function groups(){return spec.groups.map(([label,value])=>{const subset=tasks.filter(t=>t[spec.field]===value);const values={};for(const [key] of available)values[key]=chartAggregate(key,metric,spec.field,value,subset);return {label,sub:`${subset.length} tasks`,values};});}
 function draw(){const gs=groups();viz.dotStrip(host.querySelector('.chart-drawing'),{groups:gs,metric,highlight:[...highlighted],title:spec.title});const fmt=v=>metric==='sr'?(v*100).toFixed(2)+'%':v.toFixed(4);host.querySelector('.chart-data .table-scroll').innerHTML=`<table><caption>${spec.title} · ${metric==='sr'?'SR (%)':'Score'}</caption><thead><tr><th>Group</th>${available.map(m=>`<th>${m[1]}</th>`).join('')}</tr></thead><tbody>${gs.map(g=>`<tr><th scope="row">${g.label} · ${g.sub}</th>${available.map(m=>`<td>${fmt(g.values[m[0]])}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
 host.addEventListener('click',e=>{const metricButton=e.target.closest('[data-metric]'),seriesButton=e.target.closest('[data-series]');if(metricButton){metric=metricButton.dataset.metric;host.querySelectorAll('[data-metric]').forEach(b=>b.setAttribute('aria-pressed',String(b===metricButton)));}else if(seriesButton){const key=seriesButton.dataset.series;if(highlighted.has(key))highlighted.delete(key);else highlighted.add(key);seriesButton.setAttribute('aria-pressed',String(highlighted.has(key)));}else return;draw();});
 host.querySelector('.chart-drawing').addEventListener('pointerover',e=>{const d=e.target.closest('[data-tip]');if(d)host.querySelector('.chart-readout').textContent=d.dataset.tip.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();});
 viz.bindTips(host);draw();viz.resizeRedraw(host,draw);
}
const taskGroupDimensions=[
 {field:'mobility',label:'Mobility',values:[['Mobile','Mobile'],['Fixed','Tabletop']]},
 {field:'precision',label:'Precision',values:[['Low','Low precision'],['Medium','Medium precision'],['High','High precision']]},
 {field:'horizon',label:'Task horizon',values:[['Short Horizon','Short horizon'],['Long Horizon','Long horizon']]}
];
function taskGroupOptions(){return `<option value="all">All tasks (${tasks.length})</option>`+taskGroupDimensions.map(d=>`<optgroup label="${d.label}">${d.values.map(([value,label])=>`<option value="${d.field}:${value}">${label} (${tasks.filter(t=>t[d.field]===value).length})</option>`).join('')}</optgroup>`).join('');}
function matchesTaskGroup(task,group){if(group==='all')return true;const [field,value]=group.split(':');return taskGroupDimensions.some(d=>d.field===field&&d.values.some(v=>v[0]===value))&&task[field]===value;}
function taskResultsMarkup(){return `<div class="task-explorer"><p>Task-level means from the retained benchmark results. Select a metric, filter tasks, or sort a model column. Videos show individual episodes. Cells share one 0–1 color scale (0–100% for SR).</p><p><a class="appendix-link" href="data/report-tasks.csv" download>Download task data CSV ↗</a></p><div class="task-table-controls"><label>Find task <input class="task-search" type="search" placeholder="e.g. peg, frame, dishwasher"></label><label>Metric <select class="task-metric" aria-label="Metric"><option value="sr">Success rate (%)</option><option value="score">Score</option></select></label><label>Task attribute <select class="task-group" aria-label="Task attribute">${taskGroupOptions()}</select></label></div><p class="task-count fineprint" aria-live="polite"></p><div class="table-scroll task-table" tabindex="0" role="region" aria-label="26-task benchmark heatmap"></div><div class="heat-legend"><span>Shared absolute scale</span><span>0</span><i></i><span>1</span></div></div>`;}
function initTaskTable(){document.querySelectorAll('.task-explorer:not([data-table-bound])').forEach(root=>{root.dataset.tableBound='true';const orderedModels=chartModels;const host=root.querySelector('.task-table');let sortKey='Astra (ICL)',descending=true;
 const draw=()=>{const metric=root.querySelector('.task-metric').value,query=root.querySelector('.task-search').value.trim().toLowerCase(),group=root.querySelector('.task-group').value;
 const rows=tasks.filter(t=>title(t.task).toLowerCase().includes(query)&&matchesTaskGroup(t,group)).sort((a,b)=>{const delta=sortKey==='task'?a.task.localeCompare(b.task):Number(a[sortKey+'_'+metric])-Number(b[sortKey+'_'+metric]);return descending?-delta:delta;});
 root.querySelector('.task-count').textContent=`${rows.length} of ${tasks.length} tasks · select a column heading to sort`;
 const heading=(key,label)=>`<th scope="col"${key===sortKey?` aria-sort="${descending?'descending':'ascending'}"`:''}><button data-sort="${key}">${label}${key===sortKey?(descending?' ↓':' ↑'):''}</button></th>`;
 host.innerHTML=`<table class="task-results"><thead><tr>${heading('task','Task')}<th>N</th>${orderedModels.map(([key,label])=>heading(key,label)).join('')}<th>Video</th></tr></thead><tbody>${rows.map(t=>`<tr><th scope="row">${title(t.task)}</th><td>${t.episodes}</td>${orderedModels.map(([key,label])=>`<td title="${title(t.task)} · ${label}: ${metric==='sr'?(Number(t[key+'_sr'])*100).toFixed(2)+'%':Number(t[key+'_score']).toFixed(4)}" style="background:${heatColor(Number(t[key+'_'+metric]))};color:${heatInk(Number(t[key+'_'+metric]))}"${key==='Astra (ICL)'?' class="astra-cell"':''}>${metric==='sr'?(Number(t[key+'_sr'])*100).toFixed(2)+'%':Number(t[key+'_score']).toFixed(4)}</td>`).join('')}<td><button class="text-link" data-task-video="${t.task}">Watch ↗</button></td></tr>`).join('')||'<tr><td colspan="11">No matching tasks.</td></tr>'}</tbody></table>`;
 };
 root.querySelector('.task-search').addEventListener('input',draw);root.querySelector('.task-metric').addEventListener('change',draw);root.querySelector('.task-group').addEventListener('change',draw);host.addEventListener('click',e=>{const b=e.target.closest('[data-sort]');if(!b)return;descending=b.dataset.sort===sortKey?!descending:b.dataset.sort!=='task';sortKey=b.dataset.sort;draw();host.querySelector(`[data-sort="${sortKey}"]`).focus();});draw();});}

function chartAggregate(key,metric,field,group,subset){const model=reportFigures.models?.find(m=>m.id===key);if(model){const value=field?model.groups[group]?.[metric]:model[metric];if(value!==undefined)return value;}return subset.reduce((sum,t)=>sum+Number(t[key+'_'+metric]),0)/subset.length;}

// Shared absolute scale for both heatmaps, with luminance-based text contrast.
function heatRGB(value){
 const stops=[[242,245,255],[187,201,251],[49,84,215],[39,62,178],[20,37,111]];
 const position=Math.max(0,Math.min(1,value))*4,index=Math.min(3,Math.floor(position)),fraction=position-index;
 return stops[index].map((channel,i)=>Math.round(channel+(stops[index+1][i]-channel)*fraction));
}
function heatColor(value){return `rgb(${heatRGB(value).join(',')})`;}
function heatInk(value){
 const linear=heatRGB(value).map(channel=>{const c=channel/255;return c<=.04045?c/12.92:((c+.055)/1.055)**2.4;});
 const luminance=.2126*linear[0]+.7152*linear[1]+.0722*linear[2];
 return 1.05/(luminance+.05)>=(luminance+.05)/.05?'#fff':'#000';
}
